SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "沐英", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "定远人，父母亡，朱元璋收养、赐朱姓。", "biography": null, "status": "draft", "id": "c9e9d78a-2557-5892-876e-b1e99dd22bed"}, {"name": "蓝玉", "aliases": ["藍玉"], "era": "明", "birth_year": null, "death_year": null, "description": "明初将领。本纪载其以都督身份随西平侯沐英征讨西番。", "biography": null, "status": "draft", "id": "b9acd0d9-69b0-5100-b509-064627c8b88a"}, {"name": "汤和", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年夺桥取和阳，后从朱渡江。", "biography": null, "status": "draft", "id": "76a3c1b3-e175-593d-99d7-63da30cef072"}, {"name": "傅友德", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "原陈友谅小孤山守将，1361年降吴。", "biography": null, "status": "draft", "id": "052c6ab9-234a-5d89-9bad-ec31f6774b50"}, {"status": "draft", "name": "朱元璋", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "钟离人，少因饥疫丧家出家皇觉寺，1352年投郭子兴于濠州，后娶其养女。", "biography": null, "id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e"}, {"name": "朱棣", "aliases": ["明成祖"], "era": "明", "birth_year": null, "death_year": null, "description": "明成祖，建文4年（1402年），朱棣即皇帝位。", "biography": null, "status": "draft", "id": "dd806a37-77e8-5244-96e9-4d71db81b600"}]'::jsonb)
