1389, "end_year": 1389, "time_original": "洪武二十二年二月壬戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7d191709-454d-5277-b958-6d7b9e67fa15"}, {"title": "叶昇平定夏得忠起事", "description": "湖广千户夏得忠联络九溪当地人起事。靖宁侯叶昇率兵平定，夏得忠被处死。", "start_year": 1389, "end_year": 1389, "time_original": "洪武二十二年二月癸亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ce3fab3e-eec3-54f5-8dfc-030ee5a8c1e0"}, {"title": "阿资归降", "description": "本纪记载，阿资在二月归降。", "start_year": 1389, "end_year": 1389, "time_original": "洪武二十二年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "40102a0e-de04-535b-bc24-8a4d607e56a2"}, {"title": "傅友德率诸将分驻四川和湖广", "description": "傅友德率诸将分驻四川和湖广，防备本纪所称的西南诸部。", "start_year": 1389, "end_year": 1389, "time_original": "洪武二十二年三月庚午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e4e501fa-4ae2-57ae-ab89-67de9f78af9e"}, {"title": "明廷迁江南百姓到淮南耕种", "description": "朝廷将江南百姓迁到淮南耕种，发给宝钞置办农具，免除三年差役。", "start_year": 1389, "end_year": 1389, "time_original": "洪武二十二年四月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "27134382-016c-5929-b297-cdda7328fd5c"}, {"title": "徐允恭和常昇等人在湖广练兵", "description": "魏国公徐允恭、开国公常昇等人在湖广训练军队。", "start_year": 1389, "end_year": 1389, "time_original": "洪武二十二年四月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ae6a5221-0986-54b3-827d-017b09119c2d"}, {"title": "明廷迁置归降的元王", "description": "朝廷将归降的元朝王公迁往本纪所写的眈罗。", "start_year": 1389, "end_year": 1389, "time_original": "洪武二十二年四月甲寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "698f176c-c622-5a85-8345-13c893b6c51b"}, {"title": "明廷派御史调查山东官员瞒报灾情", "description": "朝廷派御史调查山东官员隐瞒灾情、不予上报的情况。", "start_year": 1389, "end_year": 1389, "time_original": "洪武二十二年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "17abdb47-d43f-5f47-9842-df611ed3ab8b"}, {"title": "明廷在兀良哈设置泰宁朵颜福余三卫", "description": "朝廷在兀良哈设置泰宁、朵颜、福余三卫。", "start_year": 1389, "end_year": 1389, "time_original": "洪武二十二年五月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "38f4d38f-3c9e-5d30-b1b0-9c7c1a82cbc3"}, {"title": "傅友德等人返回", "description": "本纪记载，七月傅友德等人返回。", "start_year": 1389, "end_year": 1389, "time_original": "洪武二十二年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a6465988-b60d-510b-9343-68df3dca0029"}, {"title": "明廷下诏荐举年长而熟悉政务的人", "description": "朝廷下诏，各地荐举有德行并熟悉时务的年长人士。", "start_year": 1389, "end_year": 1389, "time_original": "洪武二十二年八月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c4350b1e-134a-51a6-9999-62d7aa97a01a"}, {"title": "明廷重新修订《大明律》", "description": "本纪记载，朝廷在这个月重新修订《大明律》。", "start_year": 1389, "end_year": 1389, "time_original": "洪武二十二年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "efd0ea4a-17b0-5b4a-936a-2f3fbcc163a4"}, {"title": "本纪记九月初一日食", "description": "本纪记载，九月初一出现日食。", "start_year": 1389, "end_year": 1389, "time_original": "洪武二十二年九月丙寅朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "475295eb-560b-5cfc-9d1a-bb2e38aadd8c"}, {"title": "金镇等人在湖广练兵", "description": "宣德侯金镇等人在湖广训练军队。", "start_year": 1389, "end_year": 1389, "time_original": "洪武二十二年十一月丙寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1fc92bf1-2c92-5713-9e53-9b1d32931f6c"}, {"title": "思伦发来贡谢罪，麓川战事平定", "description": "本纪记载，思伦发来贡谢罪，麓川的战事至此平定。", "start_year": 1389, "end_year": 1389, "time_original": "洪武二十二年十一月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "043aa93d-f019-5e23-b99d-7ae6a978d826"}, {"title": "周王朱橚获罪后被命留京", "description": "周王朱橚获罪，朝廷起初下令迁他去云南。不久取消迁移命令，将他留在京师。", "start_year": 1390, "end_year": 1390, "time_original": "洪武二十二年十二月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8d05f826-c052-5cb2-a15c-eec97100c7a5"}, {"title": "王弼等人在山西河南陕西练兵", "description": "定远侯王弼等人在山西、河南和陕西训练军队。 按原历纪年，事情发生在公元1389至1390年之间。", "start_year": null, "end_year": null, "time_original": "洪武二十二年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "60c13492-46d7-503a-8e32-7fd82aa03fa0"}, {"title": "高丽等地遣使来贡", "description": "本纪记载，高丽、安南、占城、暹罗和真腊在这一年入贡。 按原历纪年，事情发生在公元1389至1390年之间。", "start_year": null, "end_year": null, "time_original": "洪武二十二年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3288e23f-f670-518f-9f7c-4e80384c0cfc"}, {"title": "本纪记高丽先后废黜两位君主", "description": "本纪在本年记高丽先后废黜君主禑和昌。两次废立的具体日期需分别核对。 按原历纪年，事情发生在公元1389至1390年之间。", "start_year": null, "end_year": null, "time_original": "洪武二十二年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5a4f62bd-e261-539f-9915-ef6f188950cf"}, {"title": "本纪记安南黎季犛又弑其君", "description": "本纪在本年记黎季犛再次杀害安南君主，这次的君主名为日。 按原历纪年，事情发生在公元1389至1390年之间。", "start_year": null, "end_year": null, "time_original": "洪武二十二年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "857ca945-24c9-5089-9e20-2f429a75f007"}]'::jsonb)
